public class NumericPromotionProbe {
 public class Sample {public Double quantity {get;set;}}
 public static String observe(){
  Sample sample=new Sample();sample.quantity=13.25;Double divisor=2.5;Long whole=2L;
  Map<String,Object> out=new Map<String,Object>();
  out.put('addition',String.valueOf(Decimal.valueOf(sample.quantity+2).setScale(2)));
  out.put('subtraction',String.valueOf(Decimal.valueOf(sample.quantity-2).setScale(2)));
  out.put('multiplication',String.valueOf(Decimal.valueOf(sample.quantity*2).setScale(2)));
  out.put('division',String.valueOf(Decimal.valueOf(sample.quantity/2).setScale(2)));
  out.put('doubleDivision',String.valueOf(Decimal.valueOf(sample.quantity/divisor).setScale(2)));
  out.put('longDivision',String.valueOf(Decimal.valueOf(sample.quantity/whole).setScale(2)));
  out.put('reversedDivision',String.valueOf(Decimal.valueOf(2/sample.quantity).setScale(2)));
  out.put('nestedDivision',String.valueOf(Decimal.valueOf((sample.quantity+2)/2).setScale(2)));
  out.put('direct',String.valueOf(Decimal.valueOf(sample.quantity).setScale(2)));
  out.put('string',String.valueOf(Decimal.valueOf('1.50')));
  out.put('integralDivision',String.valueOf(Decimal.valueOf(50/4).setScale(2)));
  return JSON.serialize(out);
 }
}

